 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # A rectangular outline is a uniform-color perimeter enclosing a uniform
    # interior of a different color. Fill according to frame size.
    candidates = []
    for r0 in range(h - 2):
        for r1 in range(r0 + 2, h):
            for c0 in range(w - 2):
                for c1 in range(c0 + 2, w):
                    border_color = grid[r0][c0]
                    if any(grid[r0][c] != border_color or grid[r1][c] != border_color
                           for c in range(c0, c1 + 1)):
                        continue
                    if any(grid[r][c0] != border_color or grid[r][c1] != border_color
                           for r in range(r0, r1 + 1)):
                        continue
                    interior = grid[r0 + 1][c0 + 1]
                    if interior == border_color:
                        continue
                    if any(grid[r][c] != interior
                           for r in range(r0 + 1, r1)
                           for c in range(c0 + 1, c1)):
                        continue
                    candidates.append((r0, r1, c0, c1, 7 if max(r1-r0+1, c1-c0+1) <= 5 else 2))
    # Prefer maximal outlines to avoid interpreting subrectangles inside a filled area.
    for r0, r1, c0, c1, fill in candidates:
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                out[r][c] = fill
    return out

