 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    frames = []
    # Find complete rectangular frames with a uniform, non-frame interior.
    for r0 in range(h - 2):
        for r1 in range(r0 + 2, h):
            for c0 in range(w - 2):
                for c1 in range(c0 + 2, w):
                    color = grid[r0][c0]
                    if any(grid[r0][c] != color or grid[r1][c] != color for c in range(c0, c1 + 1)):
                        continue
                    if any(grid[r][c0] != color or grid[r][c1] != color for r in range(r0, r1 + 1)):
                        continue
                    inner = grid[r0 + 1][c0 + 1]
                    if inner == color:
                        continue
                    if any(grid[r][c] != inner for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)):
                        continue
                    # Small frames and non-square interiors are marked 7;
                    # larger square interiors are marked 2.
                    ih, iw = r1-r0-1, c1-c0-1
                    fill = 2 if ih == iw and ih >= 4 else 7
                    frames.append((r0, r1, c0, c1, fill))
    for r0, r1, c0, c1, fill in frames:
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                out[r][c] = fill
    return out

