            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx,ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx,ny))
                        q.append((nx,ny))
            r0 = min(x for x,y in comp); r1 = max(x for x,y in comp)
            c0 = min(y for x,y in comp); c1 = max(y for x,y in comp)
            perimeter = {(x,y) for x in range(r0,r1+1) for y in range(c0,c1+1)
                         if x in (r0,r1) or y in (c0,c1)}
            if r1-r0 < 2 or c1-c0 < 2 or set(comp) != perimeter:
                continue
            # The size of the enclosed blank determines its marker color.
            ih, iw = r1-r0-1, c1-c0-1
            fill = 7 if max(ih, iw) <= 3 else 2
            for x in range(r0+1,r1):
