{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-medium-rnd0/frozen/seen/play/users/u036/system/state/workspace/programs/task-7f7e9aea.py",
 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx,ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx,ny))
                        q.append((nx,ny))
            r0, r1 = min(x for x,y in cells), max(x for x,y in cells)
            c0, c1 = min(y for x,y in cells), max(y for x,y in cells)
            perimeter = {(x,y) for x in range(r0,r1+1) for y in range(c0,c1+1)
                         if x in (r0,r1) or y in (c0,c1)}
            if r1-r0 < 2 or c1-c0 < 2 or set(cells) != perimeter:
                continue
            # Even-sided hollow frames are filled with 2; odd-sided frames with 7.
            side = r1-r0+1
            fill = 2 if side % 2 == 0 else 7
            for x in range(r0+1, r1):
                for y in range(c0+1, c1):
                    out[x][y] = fill
    return out

if __name__ == '__main__':
    pass
",
 "cross_profile": false
}

