 "content": "from collections import Counter, deque


def transform(grid):
    """Fill each hollow square: even side length with 2, odd with 7."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue

            queue = deque([(r, c)])
            seen.add((r, c))
            component = []
            while queue:
                x, y = queue.popleft()
                component.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen
                            and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        queue.append((nx, ny))

            r0 = min(x for x, _ in component)
            r1 = max(x for x, _ in component)
            c0 = min(y for _, y in component)
            c1 = max(y for _, y in component)
            perimeter = {
                (x, y)
                for x in range(r0, r1 + 1)
                for y in range(c0, c1 + 1)
                if x in (r0, r1) or y in (c0, c1)
            }
            if r1 - r0 < 2 or c1 - c0 < 2 or set(component) != perimeter:
                continue

            height, width = r1 - r0 + 1, c1 - c0 + 1
            if height != width:
                continue
            fill = 2 if height % 2 == 0 else 7
            for x in range(r0 + 1, r1):
                for y in range(c0 + 1, c1):
                    out[x][y] = fill

    return out


if __name__ == "__main__":
    pass
